+public class ZipService {
+
+    /**
+     * Extracts a ZIP file to the specified target path.
+     *
+     * @param zipFilePath  the path to the ZIP file to extract
+     * @param extractPath  the target directory for extraction
+     * @return a list of absolute paths of all extracted files
+     * @throws FileNotFoundException    if the ZIP file does not exist
+     * @throws SecurityException        if the ZIP file or target directory cannot be accessed
+     * @throws IllegalArgumentException if either path is null or empty
+     * @throws IOException              if an I/O error occurs during extraction
+     */
+    public List<String> extractZipFile(String zipFilePath, String extractPath) throws IOException {
+        if (zipFilePath == null || zipFilePath.isBlank()) {
+            throw new IllegalArgumentException("zipFilePath must not be null or empty");
+        }
+        if (extractPath == null || extractPath.isBlank()) {
+            throw new IllegalArgumentException("extractPath must not be null or empty");
+        }
+
+        File zipFile = new File(zipFilePath);
+        if (!zipFile.exists()) {
+            throw new FileNotFoundException("ZIP file not found: " + zipFilePath);
+        }
+        if (!zipFile.isFile()) {
+            throw new IOException("Not a regular file: " + zipFilePath);
+        }
+        if (!zipFile.canRead()) {
+            throw new SecurityException("Insufficient permissions to read ZIP file: " + zipFilePath);
+        }
+
+        File destDir = new File(extractPath);
+        if (!destDir.exists()) {
+            if (!destDir.mkdirs()) {
+                throw new IOException("Failed to create target directory: " + extractPath);
+            }
+        }
+        if (!destDir.isDirectory()) {
+            throw new IOException("Target path is not a directory: " + extractPath);
+        }
+        if (!destDir.canWrite()) {
+            throw new SecurityException("Insufficient permissions to write to target directory: " + extractPath);
+        }
+
+        String destCanonicalPath = destDir.getCanonicalPath() + File.separator;
+        List<String> extractedFiles = new ArrayList<>();
+
+        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile))) {
+            ZipEntry entry;
+            while ((entry = zis.getNextEntry()) != null) {
+                String entryName = entry.getName();
+                File targetFile = new File(destDir, entryName);
+
+                // Prevent ZIP slip: ensure the resolved path is within the target directory
+                String targetCanonicalPath = targetFile.getCanonicalPath();
+                if (!targetCanonicalPath.startsWith(destCanonicalPath)) {
+                    throw new SecurityException(
+                            "ZIP entry is outside the target directory: " + entryName);
+                }
+
+                if (entry.isDirectory()) {
+                    if (!targetFile.isDirectory() && !targetFile.mkdirs()) {
+                        throw new IOException("Failed to create directory: " + targetCanonicalPath);
+                    }
+                } else {
+                    // Ensure parent directories exist
+                    File parentDir = targetFile.getParentFile();
+                    if (parentDir != null && !parentDir.exists()) {
+                        if (!parentDir.mkdirs()) {
+                            throw new IOException("Failed to create parent directory: " + parentDir.getCanonicalPath());
+                        }
+                    }
+
+                    // Write the file content
+                    try (OutputStream os = new FileOutputStream(targetFile)) {
+                        byte[] buffer = new byte[8192];
+                        int bytesRead;
+                        while ((bytesRead = zis.read(buffer)) != -1) {
+                            os.write(buffer, 0, bytesRead);
+                        }
+                    }
+
+                    extractedFiles.add(targetFile.getCanonicalPath());
+                }
+
+                zis.closeEntry();
+            }
+        }
+
+        return extractedFiles;
+    }
